CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float mish_f(float x) {
    float sp = (x > 20.0f) ? x : log1pf(expf(x));
    return x * tanhf(sp);
}

// Scalar Mish kernel for tail elements
__global__ void mish_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    int n
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        out[idx] = mish_f(inp[idx]);
    }
}

// Vectorized Mish kernel (float4)
__global__ void mish_kernel_vec4(
    const float4* __restrict__ inp,
    float4* __restrict__ out,
    int vec_elems
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < vec_elems) {
        float4 v = inp[idx];
        v.x = mish_f(v.x);
        v.y = mish_f(v.y);
        v.z = mish_f(v.z);
        v.w = mish_f(v.w);
        out[idx] = v;
    }
}

// Scalar fused Mish+BN eval kernel
__global__ void mish_bn_eval_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias_vec,
    float eps,
    int N, int C, int HW
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * HW;
    if (idx < total) {
        int c = (idx / HW) % C;
        float rm = __ldg(&running_mean[c]);
        float rv = __ldg(&running_var[c]);
        float w  = __ldg(&weight[c]);
        float b  = __ldg(&bias_vec[c]);
        float scale = w / sqrtf(rv + eps);
        float shift = b - scale * rm;
        float y = mish_f(inp[idx]);
        out[idx] = scale * y + shift;
    }
}

// Vectorized fused Mish+BN eval kernel (float4)
__global__ void mish_bn_eval_kernel_vec4(
    const float4* __restrict__ inp,
    float4* __restrict__ out,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias_vec,
    float eps,
    int C, int HW
) {
    int vidx = blockIdx.x * blockDim.x + threadIdx.x;
    // Each vidx corresponds to 4 scalar elements starting at scalar index vidx*4
    int base = vidx * 4;
    float4 v = inp[vidx];

    // Compute per-lane channel indices
    int c0 = (base       / HW) % C;
    int c1 = ((base + 1) / HW) % C;
    int c2 = ((base + 2) / HW) % C;
    int c3 = ((base + 3) / HW) % C;

    float scale0 = __ldg(&weight[c0]) / sqrtf(__ldg(&running_var[c0]) + eps);
    float scale1 = __ldg(&weight[c1]) / sqrtf(__ldg(&running_var[c1]) + eps);
    float scale2 = __ldg(&weight[c2]) / sqrtf(__ldg(&running_var[c2]) + eps);
    float scale3 = __ldg(&weight[c3]) / sqrtf(__ldg(&running_var[c3]) + eps);

    float shift0 = __ldg(&bias_vec[c0]) - scale0 * __ldg(&running_mean[c0]);
    float shift1 = __ldg(&bias_vec[c1]) - scale1 * __ldg(&running_mean[c1]);
    float shift2 = __ldg(&bias_vec[c2]) - scale2 * __ldg(&running_mean[c2]);
    float shift3 = __ldg(&bias_vec[c3]) - scale3 * __ldg(&running_mean[c3]);

    float4 result;
    result.x = scale0 * mish_f(v.x) + shift0;
    result.y = scale1 * mish_f(v.y) + shift1;
    result.z = scale2 * mish_f(v.z) + shift2;
    result.w = scale3 * mish_f(v.w) + shift3;
    out[vidx] = result;
}

torch::Tensor mish_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "mish_cuda: input must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "mish_cuda: input must be float32");
    TORCH_CHECK(x.is_contiguous(), "mish_cuda: input must be contiguous");
    auto out = torch::empty_like(x);
    int n = x.numel();
    const int threads = 256;

    float* inp_ptr = x.data_ptr<float>();
    float* out_ptr = out.data_ptr<float>();

    bool aligned = (reinterpret_cast<uintptr_t>(inp_ptr) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(out_ptr) % 16 == 0);
    int vec_elems = n / 4;
    int tail = n % 4;

    if (aligned && vec_elems > 0) {
        int blocks_vec = (vec_elems + threads - 1) / threads;
        mish_kernel_vec4<<<blocks_vec, threads>>>(
            reinterpret_cast<const float4*>(inp_ptr),
            reinterpret_cast<float4*>(out_ptr),
            vec_elems
        );
        if (tail > 0) {
            int tail_offset = vec_elems * 4;
            int blocks_tail = (tail + threads - 1) / threads;
            mish_kernel<<<blocks_tail, threads>>>(
                inp_ptr + tail_offset, out_ptr + tail_offset, tail
            );
        }
    } else {
        int blocks = (n + threads - 1) / threads;
        mish_kernel<<<blocks, threads>>>(inp_ptr, out_ptr, n);
    }
    return out;
}

