    TORCH_CHECK(x.dim() == 4, "mish_bn_eval_cuda: input must be 4D NCHW");
    int N = x.size(0), C = x.size(1), H = x.size(2), W = x.size(3);
    int HW = H * W;
    int total = N * C * HW;
    auto out = torch::empty_like(x);
    const int threads = 256;

    auto rm_c = running_mean.contiguous();
    auto rv_c = running_var.contiguous();
    auto w_c  = weight.contiguous();
    auto b_c  = bias.contiguous();

    float* inp_ptr = x.data_ptr<float>();
    float* out_ptr = out.data_ptr<float>();

    bool aligned = (reinterpret_cast<uintptr_t>(inp_ptr) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(out_ptr) % 16 == 0);
    int vec_elems = total / 4;
    int tail = total % 4;

    if (aligned && vec_elems > 0) {
        int blocks_vec = (vec_elems + threads - 1) / threads;
