                inp_ptr + tail_offset,
                out_ptr + tail_offset,
                rm_c.data_ptr<float>(),
                rv_c.data_ptr<float>(),
                w_c.data_ptr<float>(),
                b_c.data_ptr<float>(),
                (float)eps,
                N, C, HW
